import fs from 'fs';
import path from 'path';
import { createRequire } from 'module';
import { fileURLToPath } from 'url';

const require = createRequire(import.meta.url);
// typescript ships as CJS without an `exports` field; use createRequire so the
// CJS resolver can find it even when pnpm hoists it to a parent node_modules.
const ts = require('typescript');

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const repoRoot = path.join(__dirname, '..');
const distDir = path.join(repoRoot, 'dist');

const BANNED_APIS = new Set(['fetch', 'WebSocket', 'XMLHttpRequest', 'sendBeacon']);

// `fetch` is allowed only at call sites that are individually authorized. A chunk
// is never authorized as a whole, and only real string literals in the compiled
// AST count as evidence, so a comment or an unrelated string elsewhere in the
// chunk cannot unlock network access. WebSocket, XMLHttpRequest and sendBeacon
// have no exemption anywhere.

// A fetch call is authorized when the nearest enclosing
// function contains one of these exact string literals, which identify the
// audited source function after minification.
export const AUTHORIZED_FETCH_SCOPE_LITERALS = [
  'FileReader error', // Logo/image URL loading that is routed through sanitizeSvg (svgExport)
  "pageContext couldn't be fetched because an error occurred on the server-side", // Vike client router pageContext.json requests
  'zxing-reader-wasm unavailable, scanning with qr-decode:', // Scanner: same-origin fetch of its own zxing-wasm reader (ADR 0023)
  'wasm-runtime: same-origin module fetch failed with HTTP ' // src/packages/wasm-runtime: same-origin fetch of our own Rust modules (ADR 0033)
];

// Generated files (paths relative to dist/, POSIX separators) in which `fetch`
// is part of the file's purpose. The path is fixed by the build, so no source
// content can add a file to this list.
export const AUTHORIZED_FETCH_FILES = [
  'client/sw.js' // Service worker generated by scripts/generate_sw.cjs: cache-first proxy that forwards misses
];

/**
 * Recursively list all .js and .mjs files under a directory.
 */
function findJsFiles(dir) {
  let results = [];
  if (!fs.existsSync(dir)) return results;
  const list = fs.readdirSync(dir);
  list.forEach(file => {
    const fullPath = path.join(dir, file);
    const stat = fs.statSync(fullPath);
    if (stat && stat.isDirectory()) {
      results = results.concat(findJsFiles(fullPath));
    } else if (file.endsWith('.js') || file.endsWith('.mjs')) {
      results.push(fullPath);
    }
  });
  return results;
}

/**
 * Evaluates a string node, including constant binary concatenation and template strings.
 */
function evaluateExpression(node) {
  if (ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node)) {
    return node.text;
  }
  if (ts.isBinaryExpression(node) && node.operatorToken.kind === ts.SyntaxKind.PlusToken) {
    const left = evaluateExpression(node.left);
    const right = evaluateExpression(node.right);
    if (left !== null && right !== null) {
      return left + right;
    }
  }
  if (ts.isTemplateExpression(node)) {
    let text = node.head.text;
    for (const span of node.templateSpans) {
      const expr = evaluateExpression(span.expression);
      if (expr === null) return null;
      text += expr + span.literal.text;
    }
    return text;
  }
  return null;
}

const isFunctionLike = node =>
  ts.isFunctionDeclaration(node) ||
  ts.isFunctionExpression(node) ||
  ts.isArrowFunction(node) ||
  ts.isMethodDeclaration(node) ||
  ts.isGetAccessorDeclaration(node) ||
  ts.isSetAccessorDeclaration(node) ||
  ts.isConstructorDeclaration(node);

/**
 * Collects the text of every string/template literal inside a node.
 */
function collectStringLiterals(root) {
  const literals = [];
  (function walk(node) {
    if (ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node)) {
      literals.push(node.text);
    } else if (ts.isTemplateExpression(node)) {
      literals.push(node.head.text, ...node.templateSpans.map(span => span.literal.text));
    }
    ts.forEachChild(node, walk);
  })(root);
  return literals;
}

/**
 * Decides whether the `fetch` reference at `node` is an authorized call site.
 *
 * @param {import('typescript').Node} node Identifier, property access or element access naming fetch.
 * @returns {boolean}
 */
export function isAuthorizedFetchSite(node) {
  let scope = node.parent;
  while (scope && !isFunctionLike(scope)) {
    scope = scope.parent;
  }
  if (!scope) return false;
  const literals = collectStringLiterals(scope);
  return AUTHORIZED_FETCH_SCOPE_LITERALS.some(signature => literals.includes(signature));
}

/**
 * Audit a single compiled bundle file using AST scanning.
 */
export function auditFile(filePath, baseDir = distDir) {
  const relativePath = path.relative(repoRoot, filePath).replace(/\\/g, '/');
  const distRelativePath = path.relative(baseDir, filePath).split(path.sep).join('/');
  const content = fs.readFileSync(filePath, 'utf8');

  const fileIsAuthorized = AUTHORIZED_FETCH_FILES.includes(distRelativePath);
  const fetchAllowed = site => fileIsAuthorized || isAuthorizedFetchSite(site);

  const sourceFile = ts.createSourceFile(
    filePath,
    content,
    ts.ScriptTarget.Latest,
    true
  );

  const violations = [];

  function visit(node) {
    let violationFound = false;
    let apiName = '';
    let pattern = '';

    if (ts.isIdentifier(node)) {
      const name = node.text;
      if (BANNED_APIS.has(name)) {
        // Skip safe parent contexts where the name is not a lookup/call
        const parent = node.parent;
        const isPropertyAccessName = ts.isPropertyAccessExpression(parent) && parent.name === node;
        const isPropertyAssignmentName = ts.isPropertyAssignment(parent) && parent.name === node;
        const isMethodDeclarationName = ts.isMethodDeclaration(parent) && parent.name === node;
        const isPropertySignatureName = ts.isPropertySignature(parent) && parent.name === node;
        const isMethodSignatureName = ts.isMethodSignature(parent) && parent.name === node;
        
        if (!isPropertyAccessName && !isPropertyAssignmentName && !isMethodDeclarationName && !isPropertySignatureName && !isMethodSignatureName) {
          // If fetch is found, it's only allowed if the file is authorized
          if (name !== 'fetch' || !fetchAllowed(node)) {
            violationFound = true;
            apiName = name;
            pattern = `Direct identifier '${name}'`;
          }
        }
      }
    } else if (ts.isPropertyAccessExpression(node)) {
      const propName = node.name.text;
      if (BANNED_APIS.has(propName)) {
        if (propName !== 'fetch' || !fetchAllowed(node)) {
          violationFound = true;
          apiName = propName;
          pattern = `Property access '.${propName}'`;
        }
      }
    } else if (ts.isElementAccessExpression(node)) {
      const propName = evaluateExpression(node.argumentExpression);
      if (propName && BANNED_APIS.has(propName)) {
        if (propName !== 'fetch' || !fetchAllowed(node)) {
          violationFound = true;
          apiName = propName;
          pattern = `Element access ['${propName}']`;
        }
      }
    } else {
      // Also check if any evaluated string matches a banned API
      const val = evaluateExpression(node);
      if (val && BANNED_APIS.has(val)) {
        if (val !== 'fetch' || !fileIsAuthorized) {
          violationFound = true;
          apiName = val;
          pattern = `String constant/obfuscated literal '${val}'`;
        }
      }
    }

    if (violationFound) {
      const { line, character } = sourceFile.getLineAndCharacterOfPosition(node.getStart());
      violations.push({
        file: relativePath,
        line: line + 1,
        character: character + 1,
        apiName,
        pattern,
        text: node.getText(sourceFile)
      });
    }

    ts.forEachChild(node, visit);
  }

  visit(sourceFile);
  return violations;
}

export function runBundleComplianceAudit() {
  console.log('\n=== [Bundle Compliance AST Audit] Scanning Compiled Production Bundles ===');
  console.time('AST Scan Duration');

  if (!fs.existsSync(distDir)) {
    console.warn('⚠️ [Bundle Compliance AST Audit] dist/ directory not found. Have you built the production assets?');
    return;
  }

  const jsFiles = findJsFiles(distDir);
  console.log(`[Bundle Compliance AST Audit] Found ${jsFiles.length} compiled bundle file(s) to scan.`);

  let allViolations = [];
  for (const file of jsFiles) {
    try {
      const fileViolations = auditFile(file);
      allViolations = allViolations.concat(fileViolations);
    } catch (err) {
      console.error(`❌ [Bundle Compliance AST Audit] Error scanning file ${file}:`, err.message);
    }
  }

  console.timeEnd('AST Scan Duration');

  if (allViolations.length > 0) {
    console.error(`\n❌ [BUNDLE COMPLIANCE AST AUDIT FAILURE] Detected ${allViolations.length} compliance violation(s) in compiled production bundles:\n`);

    allViolations.forEach(v => {
      console.error(`📍 Location:  ${v.file}:${v.line}:${v.character}`);
      console.error(`🏷️  Pattern:   ${v.pattern}`);
      console.error(`⚠️  Banned API: ${v.apiName}`);
      console.error(`💻 Node Text:  ${v.text}`);
      console.error('--------------------------------------------------\n');
    });

    console.error('💡 How to resolve:');
    console.error('   1. Ensure no Web Workers perform any network/fetch/WebSocket/XMLHttpRequest calls.');
    console.error('   2. Do not introduce unauthorized third-party libraries that make network requests.');
    console.error('   3. Keep client-side data privacy boundaries intact.\n');

    process.exit(1);
  }

  console.log('✅ Compiled production bundles compliance AST audit passed successfully!\n');
}

if (process.argv[1] && (process.argv[1] === fileURLToPath(import.meta.url) || process.argv[1].endsWith('bundle_ast_audit.js'))) {
  runBundleComplianceAudit();
}
